  2370  static inline unsigned int parse_sam_flag(char *v, char **rv, int *overflow) {
  2371      if (*v >= '1' && *v <= '9') {
  2372          return hts_str2uint(v, rv, 16, overflow);
  2373      }
  2374      else if (*v == '0') {
  2375          // handle single-digit "0" directly; otherwise it's hex or octal
  2376          if (v[1] == '\t') { *rv = v+1; return 0; }
  2377          else {
  2378              unsigned long val = strtoul(v, rv, 0);
  2379              if (val > 65535) { *overflow = 1; return 65535; }
  2380              return val;
  2381          }
  2382      }
  2383      else {
  2384          // TODO implement symbolic flag letters
  2385          *rv = v;
  2386          return 0;
  2387      }
  2388  }
